//! eui's sample surfaces (`vendor/eui/fixtures/`) compile from their
//! Express form against eui's core catalog.
//!
//! `tests/eui/<name>.a2ui` and `<name>.expected.json` are generated by
//! `scripts/gen-eui-express.mjs` from the pinned eui package: the expected
//! message is the fixture flattened by eui's own `flattenSurface`, with its
//! legacy bare `checks` written under the `@checks` its v1.0 catalog
//! declares.

use std::fs;
use std::path::{Path, PathBuf};

use a2ui_express::compile::Compiler;
use a2ui_express::decompile::{DecompileOptions, Order, decompile};
use a2ui_express::schema::Catalog;
use serde_json::Value;

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).to_path_buf()
}

fn read(path: &Path) -> String {
    fs::read_to_string(path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

fn compiler() -> Compiler {
    let catalog = read(&root().join("../../vendor/eui/catalog/core.schema.json"));
    let catalog = Catalog::from_json_str(&catalog).expect("eui catalog loads");
    Compiler::new(vec![catalog], None).expect("eui catalog is usable")
}

/// Order-insensitive for keys, numbers compared by value.
fn json_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => x.as_f64() == y.as_f64(),
        (Value::Array(x), Value::Array(y)) => {
            x.len() == y.len() && x.iter().zip(y).all(|(a, b)| json_eq(a, b))
        }
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len()
                && x.iter()
                    .all(|(k, v)| y.get(k).is_some_and(|w| json_eq(v, w)))
        }
        _ => a == b,
    }
}

fn check(name: &str) {
    let dir = root().join("tests/eui");
    let source = read(&dir.join(format!("{name}.a2ui")));
    let expected: Value =
        serde_json::from_str(&read(&dir.join(format!("{name}.expected.json")))).unwrap();
    let messages = compiler()
        .compile(&source, "main")
        .unwrap_or_else(|e| panic!("{name}: {} ({:?})", e.message, e.kind));
    let actual = Value::Array(messages);
    if !json_eq(&actual, &expected) {
        // Point at the first component that differs.
        let comps = |v: &Value| v[0]["createSurface"]["components"].as_array().cloned();
        if let (Some(a), Some(e)) = (comps(&actual), comps(&expected)) {
            for (a, e) in a.iter().zip(&e) {
                assert!(
                    json_eq(a, e),
                    "{name}: component differs\n got {a}\nwant {e}"
                );
            }
            assert_eq!(a.len(), e.len(), "{name}: component count");
        }
        panic!(
            "{name}: compiled messages differ\n got {}\nwant {}",
            serde_json::to_string(&actual).unwrap(),
            serde_json::to_string(&expected).unwrap()
        );
    }
}

#[test]
fn dashboard_compiles_from_express() {
    check("dashboard");
}

#[test]
fn demo_surface_compiles_from_express() {
    check("demo-surface");
}

#[test]
fn kitchen_sink_compiles_from_express() {
    check("kitchen-sink");
}

/// compile → decompile → compile reproduces the first compile exactly.
fn round_trip(name: &str) {
    let source = read(&root().join(format!("tests/eui/{name}.a2ui")));
    let compiler = compiler();
    let first = compiler
        .compile(&source, "main")
        .unwrap_or_else(|e| panic!("{name}: {} ({:?})", e.message, e.kind));
    let options = DecompileOptions {
        keyword_args: true,
        order: Order::Upstream,
    };
    let express = decompile(compiler.catalogs(), &first, &options)
        .unwrap_or_else(|e| panic!("{name}: decompile: {e}"));
    let second = compiler
        .compile(&express, "main")
        .unwrap_or_else(|e| panic!("{name}: recompile: {} ({:?})\n{express}", e.message, e.kind));
    let comps = |v: &[Value]| {
        v[0]["createSurface"]["components"]
            .as_array()
            .cloned()
            .unwrap_or_default()
    };
    let (a, b) = (comps(&first), comps(&second));
    let diffs: Vec<String> = a
        .iter()
        .zip(&b)
        .filter(|(a, b)| !json_eq(a, b))
        .map(|(a, b)| format!(" first {a}\nsecond {b}"))
        .collect();
    assert!(
        diffs.is_empty(),
        "{name}: {} component(s) differ after round-trip\n{}",
        diffs.len(),
        diffs.join("\n")
    );
    assert_eq!(a.len(), b.len(), "{name}: component count");
    assert!(
        json_eq(&Value::Array(first.clone()), &Value::Array(second.clone())),
        "{name}: messages differ after round-trip"
    );
}

#[test]
fn dashboard_round_trips() {
    round_trip("dashboard");
}

#[test]
fn demo_surface_round_trips() {
    round_trip("demo-surface");
}

#[test]
fn kitchen_sink_round_trips() {
    round_trip("kitchen-sink");
}

/// The long form `checks=[…]` lands under `@checks` like the `?check`
/// shorthand, and both forms on one component share the list.
#[test]
fn long_form_checks_use_the_envelope_key() {
    let compile = |src: &str| {
        let out = compiler().compile(src, "main").unwrap();
        out[0]["createSurface"]["components"][0].clone()
    };
    let long = compile(
        r#"root = Input(label="L", name="n", value=$/v, checks=[{condition: required(value=$/v), message: "m"}])"#,
    );
    assert!(long.get("checks").is_none(), "{long}");
    assert_eq!(long["@checks"][0]["message"], "m");

    let both = compile(
        r#"root = Input(label="L", name="n", value=$/v, checks=[{condition: required(value=$/v), message: "a"}], ?email("b"))"#,
    );
    let rules = both["@checks"].as_array().unwrap();
    let messages: Vec<&str> = rules
        .iter()
        .map(|r| r["message"].as_str().unwrap())
        .collect();
    assert_eq!(messages, ["a", "b"], "{both}");
}

/// Two eui shapes upstream's Express has no example of: a template's row
/// `key` (eui's ChildList extension), and a handler in an `on` map, whose
/// schema (`EuiAction`) has both `event` and `functionCall` as optional
/// properties. Both compile to eui's shape and survive the round trip.
#[test]
fn template_keys_and_on_handler_calls_round_trip() {
    let compiler = compiler();
    let source = r#"root = Box(children=_template($/rows, row, key="id"))
row = Button(label=$label, on={press: openUrl(url="https://example.com"), hover: Event("hovered")})
$/rows = [{id: "a", label: "A"}]
"#;
    let first = compiler
        .compile(source, "main")
        .unwrap_or_else(|e| panic!("{} ({:?})", e.message, e.kind));
    let components = first[0]["createSurface"]["components"].as_array().unwrap();
    let find = |id: &str| components.iter().find(|c| c["id"] == id).unwrap();
    assert_eq!(
        find("root")["children"],
        serde_json::json!({"path": "/rows", "componentId": "row", "key": "id"})
    );
    let on = &find("row")["on"];
    assert_eq!(on["press"]["functionCall"]["@call"], "openUrl", "{on}");
    assert_eq!(on["hover"]["event"]["name"], "hovered", "{on}");

    for order in [Order::Upstream, Order::TopDown] {
        let options = DecompileOptions {
            keyword_args: true,
            order,
        };
        let express = decompile(compiler.catalogs(), &first, &options).unwrap();
        assert!(express.contains("key=\"id\""), "{express}");
        let second = compiler
            .compile(&express, "main")
            .unwrap_or_else(|e| panic!("{} ({:?})\n{express}", e.message, e.kind));
        assert!(
            json_eq(&Value::Array(second.clone()), &Value::Array(first.clone())),
            "{order:?}:\n{express}\n{second:#?}"
        );
    }
}

/// With `keyword_args`, function calls name their arguments and leave unset
/// ones out (`formatNumber(value=…, grouping=false)`, not
/// `formatNumber(…, _, false)`), and still compile back to the same call.
#[test]
fn keyword_args_name_function_arguments() {
    let compiler = compiler();
    let source = r#"root = Text(text=formatNumber(value=$/n, grouping=false))
$/n = 1234.5
"#;
    let first = compiler.compile(source, "main").unwrap();
    for (keyword_args, expected) in [
        (true, "formatNumber(value=$/n, grouping=false)"),
        (false, "formatNumber($/n, _, false)"),
    ] {
        let options = DecompileOptions {
            keyword_args,
            order: Order::TopDown,
        };
        let express = decompile(compiler.catalogs(), &first, &options).unwrap();
        assert!(express.contains(expected), "{express}");
        let second = compiler.compile(&express, "main").unwrap();
        assert!(
            json_eq(&Value::Array(second), &Value::Array(first.clone())),
            "{express}"
        );
    }
}

/// A check whose condition is a binding, which eui's catalog allows ("a
/// condition is a binding or a call"), has no `?name(…)` shorthand. Upstream
/// writes it as `?None`, which does not compile; the decompiler writes the
/// whole list in the long form instead, and it compiles back (#AXC-18).
#[test]
fn a_binding_check_condition_round_trips_in_the_long_form() {
    let compiler = compiler();
    let input = |checks: Value| {
        vec![serde_json::json!({"version": "1.0", "createSurface": {
            "surfaceId": "main",
            "catalogId": compiler.catalogs().catalogs()[0].id(),
            "components": [{
                "id": "root", "component": "Input", "label": "L", "name": "n",
                "value": {"@path": "/v"}, "@checks": checks,
            }],
        }})]
    };
    let binding = serde_json::json!({"condition": {"@path": "/ok"}, "message": "x"});
    let call = serde_json::json!({
        "condition": {"@call": "required", "args": {"value": {"@path": "/v"}}},
        "message": "m",
    });
    for (checks, expected) in [
        (
            serde_json::json!([binding]),
            r#"checks=[{condition: $/ok, message: "x"}]"#,
        ),
        // One rule the shorthand cannot spell puts the whole list in the
        // long form, so the rules keep their order.
        (
            serde_json::json!([call, binding]),
            r#", message: "m"}, {condition: $/ok, message: "x"}]"#,
        ),
    ] {
        let first = input(checks);
        for keyword_args in [false, true] {
            for order in [Order::Upstream, Order::TopDown] {
                let options = DecompileOptions {
                    keyword_args,
                    order,
                };
                let express = decompile(compiler.catalogs(), &first, &options).unwrap();
                assert!(!express.contains("?None"), "{express}");
                assert!(express.contains(expected), "{express}");
                let second = compiler
                    .compile(&express, "main")
                    .unwrap_or_else(|e| panic!("{} ({:?})\n{express}", e.message, e.kind));
                assert!(
                    json_eq(&Value::Array(second.clone()), &Value::Array(first.clone())),
                    "{express}\n{second:#?}"
                );
            }
        }
    }
}
